fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Assumptions per problem statement:
    // - x is non-empty
    // - each row is non-empty
    // - all rows have the same length (rectangular)
    let rows = x.len();
    let cols = x[0].len();

    let mut result: Vec<Vec<f32>> = vec![vec![0.0f32; rows]; cols];

    for r in 0..rows {
        debug_assert_eq!(x[r].len(), cols, "Input must be a rectangular matrix");
        for c in 0..cols {
            result[c][r] = x[r][c];
        }
    }

    result
}